package emon;


public final class Upscaletest {
    public static int utAnswer(emon.Port.Cells ans, int id, int nlines, int xh, int w, int osd, int oconf) {
        // An OCR answer of `nlines` lines, each of one word "Hi" 40 pixels high and `w` wide, whose row x-height is `xh` (0: the engine says none); OSD says `osd` degrees
        // at the confidence `oconf` (x10; -1 for no OSD). Answers where it is.
        int at = Plan.anOcr(ans, id);
        int k = 0;
        int word = 0;
        while (k < nlines) {
            word = Plan.anOcrWord(ans, at, 10, 20 + (k * 60), w, 40, 900, k, 0);
            Plan.anOcrCp(ans, word, 72);
            Plan.anOcrCp(ans, word, 105);
            k += 1;
        }
        Ocr.oxBegin(ans, 0, 0, 0, 0, osd, 1281455214, 100, oconf, nlines, 1, 0, 0, 0);
        k = 0;
        while (k < nlines) {
            Ocr.oxLine(ans, 10, 20 + (k * 60), w, 40, 10, 55 + (k * 60), 10 + w, 55 + (k * 60), 0, 0, 0, xh, 14, 6);
            k += 1;
        }
        Ocr.oxBlock(ans, 10, 20, w, nlines * 60, 0, 0, 0);
        k = 0;
        while (k < nlines) {
            Ocr.oxWord(ans, 0, 0, -1, 0);
            k += 1;
        }
        Plan.anOcrEnd(ans, at);
        return at;
    }
    public static int utFactor(int nlines, int xh, int pxw, int pxh, int osd, int oconf) {
        emon.Port.Cells ans = emon.Port.newCells();
        int at = utAnswer(ans, 272, nlines, xh, 200, osd, oconf);
        return Upscale.upFactor(ans, at, pxw, pxh, emon.Port.newCells());
    }
    public static void testTheEffectiveResolutionIsWhatTenPointTypeAtThatXHeightHas() {
        emon.Testport.assertEq(Upscale.upEffDpi100(21), 30240, "an x-height of 21 pixels is ten point type at 302 dpi");
        emon.Testport.assertEq(Upscale.upEffDpi100(6), 8640, "6 pixels: 86 dpi, the 90 dpi page of the smoke review");
        emon.Testport.assertEq(Upscale.upEffDpi100(0), 0, "none");
        emon.Testport.assertEq(Upscale.upEffDpi100(-3), 0, "none");
    }
    public static void testTheTypicalXHeightIsTheMedianWeightedByWidth() {
        emon.Port.Cells ans = emon.Port.newCells();
        emon.Port.Cells hist = emon.Port.newCells();
        int at = utAnswer(ans, 272, 5, 6, 300, -1, -1);
        int ext = Ocr.oxFind(ans, at);
        emon.Testport.assertEq(Upscale.upXheight(ans, ext, hist), 6, "five lines of 6 pixels");
        emon.Testport.assertEq(emon.Port.cellsLen(hist), 101, "the histogram is made");
        emon.Port.Cells ans2 = emon.Port.newCells();
        int at2 = utAnswer(ans2, 272, 3, 0, 300, -1, -1);
        int ext2 = Ocr.oxFind(ans2, at2);
        emon.Testport.assertEq(Upscale.upXheight(ans2, ext2, hist), 18, "the engine says none: 45 per cent of the 40 pixel box");
    }
    public static void testSmallTextIsReadAgainEnlargedToAnXHeightOfTwenty() {
        emon.Testport.assertEq(utFactor(5, 6, 765, 990, -1, -1), 4, "6 pixels: 20 / 6 is 4 (the most)");
        emon.Testport.assertEq(utFactor(5, 7, 765, 990, -1, -1), 3, "7 pixels: 3");
        emon.Testport.assertEq(utFactor(5, 10, 765, 990, -1, -1), 2, "10 pixels: 2");
        emon.Testport.assertEq(utFactor(5, 15, 765, 990, -1, -1), 2, "15 pixels: under 16, 2");
        emon.Testport.assertEq(utFactor(5, 16, 765, 990, -1, -1), 1, "16 pixels: the text reads well, not at all");
        emon.Testport.assertEq(utFactor(5, 21, 765, 990, -1, -1), 1, "300 dpi: not at all");
        emon.Testport.assertEq(utFactor(5, 3, 765, 990, -1, -1), 4, "never more than `up-max`");
    }
    public static void testAFirstPassThatReadAlmostNothingOfASmallRasterIsReadAgainThreeTimesAsLarge() {
        // a 450 x 150 PNG of a table (smoke review A9): the engine found no line to measure
        emon.Testport.assertEq(utFactor(2, 0, 450, 150, -1, -1), 3, "two words of a small raster: enlarged 3 times");
        emon.Testport.assertEq(utFactor(0, 0, 450, 150, -1, -1), 3, "no word");
        emon.Testport.assertEq(utFactor(2, 0, 2550, 3300, -1, -1), 1, "the same of a page-sized raster: it is blank, or no text");
        emon.Testport.assertEq(utFactor(2, 0, 1400, 900, -1, -1), 3, "at the limit of `up-rescue-side`");
        emon.Testport.assertEq(utFactor(2, 0, 1401, 900, -1, -1), 1, "over it");
    }
    public static void testAPageTheEngineIsSureIsTurnedIsReadUprightFirst() {
        emon.Testport.assertEq(utFactor(5, 6, 765, 990, 90, 200), 1, "turned a quarter, OSD sure (confidence 20.0): its lines say nothing of the size");
        emon.Testport.assertEq(utFactor(5, 6, 765, 990, 180, 500), 1, "turned a half");
        emon.Testport.assertEq(utFactor(5, 6, 765, 990, 0, 500), 4, "upright and sure: measured");
        emon.Testport.assertEq(utFactor(5, 6, 765, 990, 90, 10), 4, "turned but OSD unsure (confidence 1.0): measured");
    }
    public static void testARasterWhoseEnlargementWouldPassThePixelBoundIsEnlargedLess() {
        emon.Testport.assertEq(utFactor(5, 6, 2000, 2000, -1, -1), 2, "4 million pixels: 2 times is 16 million, 3 times 36 million");
        emon.Testport.assertEq(utFactor(5, 6, 3000, 3000, -1, -1), 1, "9 million: not even twice (36 million)");
        emon.Testport.assertEq(Upscale.upMax(), 4, "the factor is at most 4");
        emon.Testport.assertEq(Upscale.upXhTrigger(), 16, "and the trigger is 16 pixels");
    }
    public static void testAReadingScoresWhatItRead() {
        emon.Port.Cells a = emon.Port.newCells();
        emon.Port.Cells b = emon.Port.newCells();
        int at = utAnswer(a, 272, 2, 6, 100, -1, -1);
        int bt = utAnswer(b, 272, 4, 6, 100, -1, -1);
        emon.Testport.assertEq(Upscale.upScore(a, at), 224, "two words of two letters at 900: 2 * (900 * 2 / 16)");
        emon.Testport.assertEq(Upscale.upScore(b, bt), 448, "four words");
        emon.Testport.assertThat(Upscale.upScore(b, bt) > Upscale.upScore(a, at), "reading more scores more");
    }
    public static void testTheCubicsWeightsSumToOneInEveryPhase() {
        emon.Port.Cells wt = emon.Port.newCells();
        int k = 2;
        while (k <= 4) {
            Upscale.upWeights(wt, k);
            int r = 0;
            while (r < (2 * k)) {
                emon.Testport.assertEq((emon.Port.cellsAt(wt, r * 4) + emon.Port.cellsAt(wt, (r * 4) + 1)) + (emon.Port.cellsAt(wt, (r * 4) + 2) + emon.Port.cellsAt(wt, (r * 4) + 3)), 1024, "the four weights of a phase sum to 1024");
                r += 1;
            }
            k += 1;
        }
        Upscale.upWeights(wt, 2);
        emon.Testport.assertEq(emon.Port.cellsAt(wt, 0), 0, "phase 0 (the input pixel's centre): the pixel itself");
        emon.Testport.assertEq(emon.Port.cellsAt(wt, 1), 1024, "all of it");
    }
    public static void testAnEnlargedRasterKeepsFlatInkAndEdges() {
        emon.Port.BitmapSet s = emon.Port.newBitmapSet();
        emon.Port.Bitmap src = emon.Port.bmsPut(s, 7, 4, 3, 1);
        emon.Port.Cells wt = emon.Port.newCells();
        int y = 0;
        int x = 0;
        // left half black (0), right half white (255); the third row all 120
        while (y < 3) {
            x = 0;
            while (x < 4) {
                if (y == 2) {
                    emon.Port.bitmapSetU8(src, x, y, 0, 120);
                } else if (x >= 2) {
                    emon.Port.bitmapSetU8(src, x, y, 0, 255);
                } else {
                    emon.Port.bitmapSetU8(src, x, y, 0, 0);
                }
                x += 1;
            }
            y += 1;
        }
        emon.Testport.assertEq(emon.Port.bmsHas(s, 9), 0, "not made yet");
        Upscale.upMake(s, 9, 10, src, 3, wt);
        emon.Testport.assertEq(emon.Port.bmsHas(s, 9), 1, "made");
        emon.Port.Bitmap big = emon.Port.bmsGet(s, 9);
        emon.Testport.assertEq(emon.Port.bitmapW(big), 12, "3 times as wide");
        emon.Testport.assertEq(emon.Port.bitmapH(big), 9, "and as high");
        emon.Testport.assertEq(emon.Port.bitmapChannels(big), 1, "one channel");
        emon.Testport.assertEq(emon.Port.bitmapU8(big, 0, 7, 0), 120, "a flat row stays flat: its left");
        emon.Testport.assertEq(emon.Port.bitmapU8(big, 11, 7, 0), 120, "and its right");
        emon.Testport.assertEq(emon.Port.bitmapU8(big, 6, 7, 0), 120, "and its middle");
        x = 1;
        while (x < 12) {
            emon.Testport.assertThat(emon.Port.bitmapU8(big, x, 0, 0) >= emon.Port.bitmapU8(big, x - 1, 0, 0), "an edge rises left to right: no ring below the black");
            x += 1;
        }
        emon.Testport.assertEq(emon.Port.bitmapU8(big, 0, 0, 0), 0, "black at the left");
        emon.Testport.assertEq(emon.Port.bitmapU8(big, 11, 0, 0), 255, "white at the right");
    }
}
